using Microsoft.EntityFrameworkCore; using NeuroPulse.Api.Models;
namespace NeuroPulse.Api.Data;
public static class SeedData {
 static readonly string[] Names={"Sarah Miller","Daniel Carter","Maya Shah","Oliver Bennett","Chloe Martin","Lucas Fischer","Sofia Rossi","Ethan Walker","Amelia Hughes","Noah Williams","Emma Clarke","Leo Evans"};
 public static async Task Reset(AppDbContext db){ await db.Database.EnsureCreatedAsync(); await db.Database.ExecuteSqlRawAsync("TRUNCATE TABLE \"Telemetry\", \"Sessions\", \"Devices\", \"Participants\" RESTART IDENTITY CASCADE");
 var now=DateTime.UtcNow; var people=Names.Select((n,i)=>{var p=n.Split(' ');return new Participant{FirstName=p[0],LastName=p[1],Email=$"{p[0].ToLower()}.{p[1].ToLower()}@example.test",DateOfBirth=new DateOnly(1982+i%15,1+i%12,2+i%20),Status=i is 9 or 11?ParticipantStatus.Inactive:ParticipantStatus.Active,CreatedAt=now.AddDays(-90-i)};}).ToList(); db.Participants.AddRange(people); await db.SaveChangesAsync();
 var states=new[]{ConnectionStatus.Connected,ConnectionStatus.Connected,ConnectionStatus.Disconnected,ConnectionStatus.Connected,ConnectionStatus.Connected,ConnectionStatus.Unknown,ConnectionStatus.Connected,ConnectionStatus.Disconnected}; var batteries=new[]{87,42,71,9,100,55,18,4}; for(int i=0;i<8;i++) db.Devices.Add(new Device{SerialNumber=$"NP-{1001+i}",Model=i<4?"NeuroBand X":"NeuroBand Mini",FirmwareVersion=i%2==0?"1.4.2":"1.3.8",BatteryPercentage=batteries[i],ConnectionStatus=states[i],AssignedParticipantId=i<4?i+1:i==5?7:null,LastSeenAt=now.AddMinutes(-i*11)}); await db.SaveChangesAsync();
 for(int i=1;i<=20;i++){var started=now.Date.AddDays(-(i%8)).AddHours(8+i%9);var s=new RecordingSession{ParticipantId=(i%9)+1,DeviceId=(i%4)+1,StartedAt=started,EndedAt=started.AddMinutes(18+i),Status=SessionStatus.Completed,AverageSignal=62+i%20,SignalQuality=.72+(i%20)/100d,Notes=i%4==0?"Routine recording; signal stabilised.":""};db.Sessions.Add(s); for(int j=0;j<4;j++)db.Telemetry.Add(new TelemetryReading{SessionId=i,DeviceId=$"NP-{1001+(i%4)}",Timestamp=started.AddMinutes(j*5),Signal=60+i+j,Quality=.75+j*.03,BatteryPercentage=80-i%30});} await db.SaveChangesAsync(); }
}
